    var target = maxLength / 5, power = Math.pow(10, Math.floor(Math.log10(target)));
    var step = [1, 2, 5, 10].map(function (n) { return n * power; }).filter(function (n) { return n >= target; })[0] || 1;
    var axisMax = Math.ceil(maxLength / step) * step;
