      p.metacarpalRatios=[.52,1,.92,.63,.16];p.phalangeLengths=[[.68],[.46,.79],[.28,.29,.66],[.16],[]];p.ungualLengths=[.77,.62,.50,0,0];p.vestigialRays=[5];
